import{_ as a,o as d,c as o,a2 as e}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"位面穿梭规则","description":"","frontmatter":{},"headers":[],"relativePath":"constitution/81-位面穿梭规则.md","filePath":"constitution/81-位面穿梭规则.md","lastUpdated":1789183869000}'),r={name:"constitution/81-位面穿梭规则.md"};function l(i,t,h,n,u,s){return d(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="位面穿梭规则" tabindex="-1">位面穿梭规则 <a class="header-anchor" href="#位面穿梭规则" aria-label="Permalink to &quot;位面穿梭规则&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>81</td></tr><tr><td>所属模块</td><td>跨位面交互与时间规则</td></tr><tr><td>核心关键词</td><td>位面穿梭、穿梭许可、能量阈值、锚点校准、污染防控</td></tr></tbody></table><h2 id="一、穿梭行为的法律定位" tabindex="-1">一、穿梭行为的法律定位 <a class="header-anchor" href="#一、穿梭行为的法律定位" aria-label="Permalink to &quot;一、穿梭行为的法律定位&quot;">​</a></h2><p>位面穿梭是指生命个体或群体通过技术手段或修炼能力，跨越法则壁垒从一个位面进入另一个位面的行为。在锚点共生文明的法律框架下，位面穿梭属于&quot;高风险特殊行为&quot;，必须受到严格的许可管理与过程监督。《共生宪法》第四十七条明确规定：&quot;任何组织和个人不得未经许可擅自进行跨位面穿梭，不得利用位面穿梭从事掠夺、干涉或污染其他位面文明的活动。&quot;</p><p>位面穿梭之所以需要严格管控，根本原因在于穿梭行为本身可能对目标位面造成多重影响：法则扰动、能量注入、意识污染、微生物入侵以及文化干涉等。这些影响轻则引发目标位面的局部异常，重则可能改变其文明演化轨迹，甚至导致法则崩溃。因此，穿梭规则的核心目标是&quot;将穿梭行为的外部影响控制在可接受的阈值之内&quot;。</p><h2 id="二、穿梭许可分级制度" tabindex="-1">二、穿梭许可分级制度 <a class="header-anchor" href="#二、穿梭许可分级制度" aria-label="Permalink to &quot;二、穿梭许可分级制度&quot;">​</a></h2><p>衡元宙实行位面穿梭许可分级制度，根据穿梭目的、目标位面类型与穿梭者资质，将许可分为四个等级：</p><table tabindex="0"><thead><tr><th>许可等级</th><th>适用场景</th><th>审批机构</th><th>有效期</th><th>附加条件</th></tr></thead><tbody><tr><td>A级（考古观测）</td><td>纯观测性考古，不进行任何物理接触</td><td>位面管理局</td><td>单次任务</td><td>必须使用复制镜+隔离空间方案</td></tr><tr><td>B级（学术交流）</td><td>与目标位面文明进行有限的知识交流</td><td>位面管理局+文化部</td><td>最长一年</td><td>须签订互不干涉协议</td></tr><tr><td>C级（资源协作）</td><td>在平等互利前提下进行资源与技术协作</td><td>锚点议事会特批</td><td>最长三年</td><td>须经目标位面文明同意</td></tr><tr><td>D级（紧急干预）</td><td>目标位面面临灭绝级危机时的人道主义干预</td><td>锚点议事会紧急决议</td><td>危机持续期</td><td>事后须提交完整干预报告</td></tr></tbody></table><p>任何等级的穿梭许可都禁止以下行为：掠夺目标位面的本源能量、强制传播本位面意识形态、未经同意进行基因或意识改造、在目标位面建立永久性军事基地、以及任何形式的殖民统治。</p><h2 id="三、穿梭技术要求与能量阈值" tabindex="-1">三、穿梭技术要求与能量阈值 <a class="header-anchor" href="#三、穿梭技术要求与能量阈值" aria-label="Permalink to &quot;三、穿梭技术要求与能量阈值&quot;">​</a></h2><p>位面穿梭需要满足严格的技术条件。首先，穿梭者必须具备&quot;空间法理调度体系&quot;第三阶（化空境）以上的修为，或搭载符合标准的位面穿梭载具。其次，穿梭起点和终点都必须有锚点进行坐标校准，无锚点定位的盲穿行为被严格禁止。</p><p>穿梭过程的能量消耗与目标位面的法则壁垒强度成正比。衡元宙建立了标准化的&quot;穿梭能量阈值表&quot;，不同类型位面的穿梭所需最低能量如下：</p><ul><li>物质本位面：1000标准能量单位</li><li>能量显化位面：5000标准能量单位</li><li>意识主导位面：20000标准能量单位</li><li>法则破碎位面：50000标准能量单位（且成功率低于30%）</li><li>本源近邻位面：理论值100000以上，目前无成功记录</li></ul><p>穿梭能量必须由穿梭者或载具自身携带，禁止从目标位面抽取能量用于穿梭过程。这一规定旨在防止穿梭行为对目标位面造成能量掠夺。</p><h2 id="四、穿梭过程的污染防控" tabindex="-1">四、穿梭过程的污染防控 <a class="header-anchor" href="#四、穿梭过程的污染防控" aria-label="Permalink to &quot;四、穿梭过程的污染防控&quot;">​</a></h2><p>位面穿梭的最大风险之一是&quot;跨位面污染&quot;，包括生物污染（携带本位面微生物进入目标位面）、能量污染（本位面能量残留对目标位面法则的干扰）与意识污染（穿梭者的意识波动影响目标位面的意识域）。</p><p>为防控污染，所有穿梭者必须在出发前完成&quot;三级净化程序&quot;：</p><ol><li><strong>生物净化</strong>：在隔离空间内进行72小时的微生物筛查与清除，确保不携带任何本位面病原体</li><li><strong>能量净化</strong>：通过锚点校准装置将穿梭者的能量频率调整至与目标位面兼容的范围，减少能量排斥反应</li><li><strong>意识净化</strong>：进行意识屏蔽训练，确保穿梭过程中不主动释放可能干扰目标位面意识域的意念波动</li></ol><p>此外，穿梭者在目标位面的活动范围被严格限定在&quot;穿梭许可划定区域&quot;内，禁止未经授权的扩散。返回本位面后，穿梭者须再次接受隔离观察，时间不少于目标位面时间流速换算后的30天。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>位面穿梭规则是跨位面交互的第一道安全防线。它通过许可分级、技术门槛与污染防控三重机制，确保穿梭行为始终在&quot;低影响、可追溯、可问责&quot;的轨道上运行。规则的终极目的不是限制文明间的交流，而是让交流以共生的方式发生，而非以掠夺的方式发生。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>80-位面理论与分类</li><li>88-跨位面伦理准则</li><li>62-空间法理技术实现</li></ul>',23)])])}const c=a(r,[["render",l]]);export{q as __pageData,c as default};
